-- Hand-added backfill. Every project predates accounts and carries a NULL org,
-- so all of them move to the seeded default org before the column turns NOT
-- NULL. The INSERT is the boot seed's job, repeated here so this migration
-- stands alone on an empty database.
--
-- No renumbering step is needed: createProject was the only writer and it
-- always inserted NULL, so uq_project_display_noorg already kept these
-- display_numbers unique. Adding them back to one org cannot collide.
INSERT INTO "organization" ("name") VALUES ('default') ON CONFLICT ("name") DO NOTHING;--> statement-breakpoint
UPDATE "project"
   SET "organization_id" = (SELECT "organization_id" FROM "organization" WHERE "name" = 'default')
 WHERE "organization_id" IS NULL;--> statement-breakpoint
